use std::{time::{Instant,Duration},thread};
fn main(){let a:Vec<String>=std::env::args().collect();let base=&a[1];assert!(base=="http://127.0.0.1:18762"||base=="https://127.0.0.1:18763");let (delay,size,fault,keep)=(&a[2],a[3].parse::<usize>().unwrap(),a[4]=="1",a[5]=="1");let rounds=a[6].parse::<usize>().unwrap();let start=Instant::now();let client=reqwest::blocking::Client::builder().no_proxy().http1_only().pool_max_idle_per_host(if keep{8}else{0}).timeout(Duration::from_secs(1)).redirect(reqwest::redirect::Policy::none()).add_root_certificate(reqwest::Certificate::from_pem(&std::fs::read("ca.pem").unwrap()).unwrap()).build().unwrap();let call=|i:usize|->String{match client.get(format!("{base}/?delay={delay}&size={size}&fault={}&id={i}",u8::from(fault))).send(){Err(e)=>if e.is_timeout(){"timeout".into()}else{"network".into()},Ok(r)=>{let code=r.status().as_u16();let body=r.bytes();if code!=200{return code.to_string()}match body.ok().and_then(|b|serde_json::from_slice::<serde_json::Value>(&b).ok()){Some(v) if v["ok"]==true&&v["data"].as_str().map(str::len)==Some(size)=>"ok".into(),_=>"invalid".into()}}}};let mut samples=vec![];for _ in 0..rounds{let t=Instant::now();let mut out=Vec::new();for j in (0..25).step_by(8){thread::scope(|s|{let jobs:Vec<_>=(j..(j+8).min(25)).map(|i|s.spawn(move||call(i))).collect();out.extend(jobs.into_iter().map(|x|x.join().unwrap()));});}for(i,v)in out.iter().enumerate(){let expected=if fault&&i<4{["503","429","timeout","invalid"][i]}else{"ok"};assert_eq!(v,expected,"case {i}");}samples.push(t.elapsed().as_secs_f64()*1000.0);}let mut m=serde_json::json!({"samples":samples,"elapsed_ms":start.elapsed().as_secs_f64()*1000.0});for l in std::fs::read_to_string("/proc/self/status").unwrap().lines(){if l.starts_with("VmHWM:")||l.starts_with("VmRSS:"){let mut x=l.split_whitespace();let k=x.next().unwrap().trim_end_matches(':');m[k]=serde_json::json!(x.next().unwrap().parse::<u64>().unwrap());}}println!("{m}");}
